<style>
.module-workspace{--module-accent:#f9a8d4;min-width:0;color:var(--color-brand-white,#fff)}
.module-workspace[data-department="operations_projects"]{--module-accent:#fbbf24}.module-workspace[data-department="finance"]{--module-accent:#67e8f9}
.module-hero{border:1px solid color-mix(in srgb,var(--module-accent) 35%,transparent);background:linear-gradient(125deg,color-mix(in srgb,var(--module-accent) 10%,transparent),transparent 65%);padding:clamp(1.2rem,3vw,2rem);border-radius:1.25rem;margin-bottom:1.5rem}
.module-hero h3{font-size:clamp(1.6rem,3vw,2.4rem);font-weight:700;line-height:1.2;margin:.5rem 0}.module-kicker{color:var(--module-accent);font-size:.7rem;letter-spacing:.15em;text-transform:uppercase}
.module-tabs{display:flex;flex-wrap:wrap;gap:.6rem;margin:1.5rem 0}.module-tabs button,.module-link{display:inline-flex;align-items:center;min-height:44px;padding:.7rem 1rem;border:1px solid #8885;border-radius:.7rem;font-size:.85rem}
.module-tabs [aria-selected=true]{border-color:var(--module-accent);background:color-mix(in srgb,var(--module-accent) 12%,transparent)}
.module-panel{min-width:0}.module-notice{border-left:3px solid var(--module-accent);padding:.8rem 1rem;background:#8881;font-size:.85rem;line-height:1.6;margin:1rem 0}
.module-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,15rem),1fr));gap:1rem}.module-form label{font-size:.8rem;min-width:0}.module-form input,.module-form select,.module-form textarea{display:block;width:100%;min-width:0;margin-top:.4rem;border:1px solid #8885;border-radius:.5rem;padding:.75rem;background:var(--color-brand-black,#161616);color:inherit}
.module-form button,.module-submit{min-height:44px;border:1px solid var(--module-accent);border-radius:.6rem;padding:.75rem 1rem}.module-scroll{max-width:100%;overflow-x:auto}.module-scroll table{width:100%;font-size:.8rem;text-align:left}.module-scroll th,.module-scroll td{padding:1rem;border-bottom:1px solid #8883;min-width:8rem;vertical-align:top}
.module-record{padding:1rem;border:1px solid #8884;border-radius:.75rem;margin:1rem 0;min-width:0;overflow-wrap:anywhere}.module-muted{font-size:.8rem;opacity:.75;line-height:1.6}.module-workspace .ck-editor{min-width:0}.module-workspace .ck-toolbar{max-height:9rem;overflow-y:auto}
[data-theme="light"] .module-workspace{--module-accent:#9d174d}[data-theme="light"] .module-workspace[data-department="operations_projects"]{--module-accent:#92400e}[data-theme="light"] .module-workspace[data-department="finance"]{--module-accent:#0e7490}
@media(prefers-reduced-motion:reduce){.module-workspace *{scroll-behavior:auto}}
</style>
